  ui_story_32120401_52_dialog_content = "Apa yang kamu lakukan pada jam 9?",
  ui_story_32120401_53_dialog_content = "Ayo ikut denganku! Sebenarnya aku ingin mengajakmu dari awal!",
  ui_story_32120401_54_dialog_content = "Haaah... Di luar sana benar-benar dingin sekali.",
  ui_story_32120401_55_dialog_content = "Apa yang kita lakukan di sini begitu larut malam...?",
  ui_story_32120401_56_dialog_content = "Aku tidak melihat apa-apa di sini.",
