  ui_story_32120401_60_dialog_content = "Setelah mengamati pergerakan bintang selama beberapa hari, aku tahu bahwa langit malam hari ini seharusnya sangat cerah.",
  ui_story_32120401_61_dialog_content = "Berbagai macam konstelasi dan galaksi terlihat malam ini.",
  ui_story_32120401_62_dialog_content = "Dan kamu selalu begitu sibuk. Aku pikir kamu tidak akan punya waktu untuk melihat kecuali ada seseorang yang membawamu ke sini untuk melihatnya.",
