  ui_story_32120401_71_dialog_content = "Dan itulah alasan mengapa saya sangat haus akan pengetahuan! Untuk mempelajari sebanyak mungkin tentang dunia di sekitar saya!",
  ui_story_32120401_72_dialog_content = "Tentu saja, akan aneh jika kita menjalani seluruh hidup kita tanpa pernah berhenti untuk bertanya-tanya bagaimana semua ini bekerja.",
