  ui_story_32120401_80_option_content = "Sesuatu terjadi di masa lalu?",
  ui_story_32120401_81_dialog_content = "Selama perjalanan, aku mencoba untuk diterima di akademi bergengsi. Aku bahkan sampai mengikuti ujian masuk mereka.",
  ui_story_32120401_82_dialog_content = "Sayangnya, pendidikan saya sama sekali tidak mempersiapkan saya, dan saya gagal dalam tes tersebut.",
